const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number(n).toLocaleString('ko-KR');
export function showEstImportReport(project,preview=false){
 const report=project.estImport;if(!report)return Promise.resolve(false);
 const d=document.createElement('dialog');d.id='estProjectReport';
 Object.assign(d.style,{width:'850px',maxWidth:'94vw',maxHeight:'90vh',overflow:'auto',padding:'20px',color:'#202832',fontSize:'14px'});
 d.innerHTML=`<div class="dialog-head"><h2>EST 공사 ${preview?'열기':'가져오기 결과'}</h2><button class="icon-btn" data-cancel aria-label="닫기">×</button></div><p><strong>${escape(project.title)}</strong><br>${escape(report.file)} · EST ${escape(report.version)}</p><p>품목 ${report.itemCount}개 · 공종·공구 ${report.levelCount}개 · 파일에 저장된 단가 사용</p>${!preview?'<p>아래 금액은 처음 가져온 시점의 대조 결과입니다. 이후 편집한 금액과는 다를 수 있습니다.</p>':''}<div class="table-wrap"><table style="width:100%"><thead><tr><th>구분</th><th>EST 원본</th><th>공사노트</th><th>차이</th></tr></thead><tbody>${report.comparisons.map(c=>`<tr><td>${escape(c.name)}</td><td class="number">${money(c.original)}</td><td class="number">${money(c.imported)}</td><td class="number">${money(c.difference)}원</td></tr>`).join('')}</tbody></table></div>${report.warnings.length?'<div style="padding:12px;background:#fff4e2;color:#6a3908;margin-top:14px"><strong>확인할 내용</strong><ul>'+report.warnings.map(w=>'<li>'+escape(w)+'</li>').join('')+'</ul></div>':'<p>원본 저장 금액과 대조를 마쳤습니다.</p>'}${report.fixedCharges.length?'<h3>원본 금액을 유지한 제경비</h3><p>표시 요율은 참고값입니다. 이 항목은 수량을 수정해도 자동으로 바뀌지 않습니다.</p><table style="width:100%"><thead><tr><th>항목</th><th>원본 요율</th><th>저장 금액</th><th>요율 재계산</th></tr></thead><tbody>'+report.fixedCharges.map(c=>`<tr><td>${escape(c.name)}</td><td>${c.rate}%</td><td>${money(c.original)}</td><td>${c.calculated==null?escape(c.reason||"산식 확인 필요"):money(c.calculated)}</td></tr>`).join('')+'</tbody></table>':''}${report.fixedRows.length?'<details><summary>금액 고정 품목 '+report.fixedRows.length+'개</summary><ul>'+report.fixedRows.map(r=>`<li>${r.record+1}행 ${escape(r.name)} · ${money(r.amount)}원</li>`).join('')+'</ul></details>':''}<details style="margin-top:12px"><summary>합산에서 제외한 원가·합계·빈 행 ${report.skipped.length}개</summary><ul>${report.skipped.map(r=>`<li>${r.record+1}행 ${escape(r.name||'')} · ${escape(r.reason)}</li>`).join('')}</ul></details><p>원본 EST 파일은 변경하지 않습니다. 수정한 작업은 공사노트 파일로 저장합니다.</p><div class="dialog-actions"><button class="button" data-cancel>${preview?'취소':'닫기'}</button>${preview?'<button class="button primary" data-accept>공사로 열기</button>':''}</div>`;
 document.body.append(d);
 return new Promise(resolve=>{let accepted=false;d.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=()=>d.close());if(preview)d.querySelector('[data-accept]').onclick=()=>{accepted=true;d.close();};d.addEventListener('close',()=>{d.remove();resolve(accepted);},{once:true});d.showModal();});
}
